function ProductsTab() {
  const BASE_URL = process.env.NEXT_PUBLIC_BASE_URL;
  const [showAddForm, setShowAddForm] = useState(false);
  const [selectedImages, setSelectedImages] = useState<File[]>([]);
  const [imagePreviews, setImagePreviews] = useState<string[]>([]);
  const [isSubmitting, setIsSubmitting] = useState(false);
  const { categories, products, productsLoading } = useProducts();

  // Handle image selection
  const handleImageSelect = (event: React.ChangeEvent<HTMLInputElement>) => {
    const files = event.target.files;
    if (!files) return;

    const newImages = Array.from(files);
    setSelectedImages((prev) => [...prev, ...newImages]);

    // Create preview URLs
    const newPreviews = newImages.map((file) => URL.createObjectURL(file));
    setImagePreviews((prev) => [...prev, ...newPreviews]);
  };

  // Remove selected image
  const removeImage = (index: number) => {
    setSelectedImages((prev) => prev.filter((_, i) => i !== index));
    setImagePreviews((prev) => prev.filter((_, i) => i !== index));
  };

  // Clean up preview URLs when component unmounts
  useEffect(() => {
    return () => {
      imagePreviews.forEach((url) => URL.revokeObjectURL(url));
    };
  }, [imagePreviews]);

  // Handle form submission
  const handleSubmit = async (event: React.FormEvent<HTMLFormElement>) => {
    event.preventDefault();
    setIsSubmitting(true);

    const formData = new FormData(event.currentTarget);

    // Append images to form data
    selectedImages.forEach((image, index) => {
      formData.append("images", image);
    });

    // DEBUG: Check what's in formData
    console.log("=== FORM DATA CONTENTS ===");
    for (let [key, value] of formData.entries()) {
      if (value instanceof File) {
        console.log(`${key}: [File] ${value.name} (${value.size} bytes)`);
      } else {
        console.log(`${key}:`, value);
      }
    }

    try {
      const response = await fetch(`${BASE_URL}/admin/products`, {
        method: "POST",
        body: formData,
        credentials: "include",
        // Don't set Content-Type header - browser will set it with boundary
      });

      if (!response.ok) {
        throw new Error("Failed to create product");
      }

      const result = await response.json();

      // Reset form after successful submission
      setSelectedImages([]);
      setImagePreviews([]);
      setShowAddForm(false);

      // Show success message
      alert("Product created successfully!");

      // Refresh the page to update products list
      window.location.reload();
    } catch (error) {
      console.error("Error creating product:", error);
      alert("Error creating product. Please try again.");
    } finally {
      setIsSubmitting(false);
    }
  };

  // Handle product deletion
  const handleDelete = async (id: string) => {
    if (
      !confirm(
        "Are you sure you want to delete this product? This action cannot be undone."
      )
    ) {
      return;
    }

    try {
      const response = await fetch(`${BASE_URL}/admin/products?id=${id}`, {
        method: "DELETE",
        credentials: "include",
      });

      if (!response.ok) {
        throw new Error("Failed to delete product");
      }

      alert("Product deleted successfully!");
      window.location.reload(); // Refresh to update products list
    } catch (error) {
      console.error("Error deleting product:", error);
      alert("Error deleting product. Please try again.");
    }
  };

  return (
    <div>
      <div className="flex flex-col lg:flex-row lg:justify-between lg:items-center gap-4 mb-6 lg:mb-8">
        <h2 className="text-2xl lg:text-3xl font-bold">Products Management</h2>
        <Button
          onClick={() => setShowAddForm(!showAddForm)}
          className="bg-black text-white hover:bg-gray-800 flex items-center space-x-2"
        >
          <Plus size={20} />
          <span>{showAddForm ? "Cancel" : "Add Product"}</span>
        </Button>
      </div>

      {showAddForm && (
        <form
          onSubmit={handleSubmit}
          className="bg-white rounded-lg p-4 lg:p-6 shadow mb-6 lg:mb-8 space-y-4"
        >
          {/* Product Name */}
          <div>
            <label className="block text-sm font-medium text-gray-700 mb-2">
              Product Name *
            </label>
            <input
              type="text"
              name="name"
              placeholder="Enter product name"
              className="w-full px-4 py-2 border rounded-lg text-sm lg:text-base"
              required
            />
          </div>

          {/* Description */}
          <div>
            <label className="block text-sm font-medium text-gray-700 mb-2">
              Description
            </label>
            <textarea
              name="description"
              placeholder="Enter product description"
              rows={3}
              className="w-full px-4 py-2 border rounded-lg text-sm lg:text-base"
            />
          </div>

          {/* Price and Stock */}
          <div className="grid grid-cols-1 md:grid-cols-2 gap-4">
            <div>
              <label className="block text-sm font-medium text-gray-700 mb-2">
                Price (₦) *
              </label>
              <input
                type="number"
                name="price"
                placeholder="0.00"
                min="0"
                step="0.01"
                className="w-full px-4 py-2 border rounded-lg text-sm lg:text-base"
                required
              />
            </div>
            <div>
              <label className="block text-sm font-medium text-gray-700 mb-2">
                Stock *
              </label>
              <input
                type="number"
                name="stock"
                placeholder="0"
                min="0"
                className="w-full px-4 py-2 border rounded-lg text-sm lg:text-base"
                required
              />
            </div>
          </div>

          {/* Category */}
          <div>
            <label className="block text-sm font-medium text-gray-700 mb-2">
              Category *
            </label>
            <select
              name="categoryId"
              className="w-full px-4 py-2 border rounded-lg text-sm lg:text-base"
              required
            >
              <option value="">Select Category</option>
              {categories.map((item, index) => (
                <option key={index} value={item.id}>
                  {item.name}
                </option>
              ))}
            </select>
          </div>

          {/* Image Upload */}
          <div>
            <label className="block text-sm font-medium text-gray-700 mb-2">
              Product Images *
            </label>

            {/* File Input */}
            <div className="border-2 border-dashed border-gray-300 rounded-lg p-6 text-center">
              <input
                type="file"
                multiple
                accept="image/*"
                onChange={handleImageSelect}
                className="hidden"
                id="product-images"
              />
              <label
                htmlFor="product-images"
                className="cursor-pointer flex flex-col items-center justify-center space-y-2"
              >
                <Upload className="text-gray-400" size={32} />
                <div>
                  <span className="text-blue-600 font-medium">
                    Click to upload
                  </span>
                  <span className="text-gray-500"> or drag and drop</span>
                </div>
                <p className="text-xs text-gray-500">
                  PNG, JPG, JPEG up to 10MB each
                </p>
              </label>
            </div>

            {/* Image Previews */}
            {imagePreviews.length > 0 && (
              <div className="mt-4">
                <p className="text-sm font-medium text-gray-700 mb-3">
                  Selected Images ({selectedImages.length})
                </p>
                <div className="grid grid-cols-2 sm:grid-cols-3 md:grid-cols-4 lg:grid-cols-5 gap-4">
                  {imagePreviews.map((preview, index) => (
                    <div key={index} className="relative group">
                      <img
                        src={preview}
                        alt={`Preview ${index + 1}`}
                        className="w-full h-24 object-cover rounded-lg border"
                      />
                      <button
                        type="button"
                        onClick={() => removeImage(index)}
                        className="absolute -top-2 -right-2 bg-red-500 text-white rounded-full p-1 opacity-0 group-hover:opacity-100 transition-opacity"
                      >
                        <X size={14} />
                      </button>
                      <div className="absolute bottom-0 left-0 right-0 bg-black bg-opacity-50 text-white text-xs p-1 rounded-b-lg truncate">
                        {selectedImages[index]?.name}
                      </div>
                    </div>
                  ))}
                </div>
              </div>
            )}
          </div>

          {/* Submit Button */}
          <Button
            type="submit"
            className="w-full bg-black text-white hover:bg-gray-800 flex items-center justify-center space-x-2"
            disabled={selectedImages.length === 0 || isSubmitting}
          >
            {isSubmitting ? (
              <>
                <div className="animate-spin rounded-full h-4 w-4 border-b-2 border-white"></div>
                <span>Creating...</span>
              </>
            ) : (
              <>
                <Plus size={20} />
                <span>Add Product</span>
              </>
            )}
          </Button>

          {selectedImages.length === 0 && (
            <p className="text-sm text-red-600 text-center">
              Please upload at least one product image
            </p>
          )}
        </form>
      )}

      {productsLoading && (
        <div className="flex justify-center py-10">
          <div className="w-6 h-6 border-4 border-gray-300 border-t-black rounded-full animate-spin"></div>
        </div>
      )}

      <div className="bg-white rounded-lg shadow overflow-hidden">
        {/* Mobile Cards View */}
        <div className="lg:hidden divide-y">
          {products.map((item) => (
            <div key={item.id} className="p-4 space-y-3">
              <div className="flex items-start space-x-3">
                {/* Product Image */}
                {item.imageUrls?.[0] && (
                  <img
                    src={item.imageUrls[0]}
                    alt={item.name}
                    className="w-16 h-16 object-cover rounded-lg border"
                  />
                )}
                <div className="flex-1">
                  <div className="flex justify-between items-start">
                    <div className="font-medium capitalize">{item.name}</div>
                    <span className="px-2 capitalize py-1 bg-blue-100 text-blue-800 rounded text-xs">
                      {item.category.name}
                    </span>
                  </div>
                  <div className="flex justify-between text-sm text-gray-600 mt-2">
                    <span>₦{item.price}</span>
                    <span>Stock: {item.stock}</span>
                  </div>
                  <div className="flex space-x-2 pt-2">
                    <button
                      onClick={() => handleDelete(item.id)}
                      className="flex items-center space-x-1 text-red-600 text-sm"
                    >
                      <Trash2 size={16} />
                      <span>Delete</span>
                    </button>
                  </div>
                </div>
              </div>
            </div>
          ))}
        </div>

        {/* Desktop Table View */}
        <div className="hidden lg:block overflow-x-auto">
          <table className="w-full text-sm">
            <thead className="bg-gray-100 border-b">
              <tr>
                <th className="text-left py-4 px-6">Image</th>
                <th className="text-left py-4 px-6">Product Name</th>
                <th className="text-left py-4 px-6">Price</th>
                <th className="text-left py-4 px-6">Stock</th>
                <th className="text-left py-4 px-6">Category</th>
                <th className="text-center py-4 px-6">Actions</th>
              </tr>
            </thead>
            <tbody>
              {products.map((item) => (
                <tr key={item.id} className="border-b hover:bg-gray-50">
                  <td className="py-4 px-6">
                    {item.imageUrls?.[0] && (
                      <img
                        src={item.imageUrls[0]}
                        alt={item.name}
                        className="w-12 h-12 object-cover rounded border"
                      />
                    )}
                  </td>
                  <td className="py-4 px-6 font-medium capitalize">
                    {item.name}
                  </td>
                  <td className="py-4 px-6">₦{item.price}</td>
                  <td className="py-4 px-6">{item.stock}</td>
                  <td className="py-4 px-6">
                    <span className="px-3 py-1 bg-blue-100 text-blue-800 rounded text-xs capitalize">
                      {item.category.name}
                    </span>
                  </td>
                  <td className="py-4 px-6 text-center space-x-2">
                    <button className="text-blue-600 hover:underline">
                      Edit
                    </button>
                    <button
                      onClick={() => handleDelete(item.id)}
                      className="text-red-600 hover:underline"
                    >
                      Delete
                    </button>
                  </td>
                </tr>
              ))}
            </tbody>
          </table>
        </div>
      </div>
    </div>
  );
}

function CategoriesTab() {
  const [showAddForm, setShowAddForm] = useState(false);
  const [name, setName] = useState("");

  // Edit modal states
  const [editingId, setEditingId] = useState<string | null>(null);
  const [editedName, setEditedName] = useState("");

  const {
    categories,
    CreateCategory,
    deleteCategory,
    editCategory,
    categoriesLoading,
    isLoading,
  } = useProducts();
  const formData = { name };

  const openEditModal = (cat: any) => {
    setEditingId(cat.id);
    setEditedName(cat.name);
  };

  const closeEditModal = () => {
    setEditingId(null);
    setEditedName("");
  };

  const handleSaveEdit = () => {
    editCategory(editingId!, { name: editedName });
    closeEditModal();
  };

  return (
    <div>
      {/* Header */}
      <div className="flex flex-col lg:flex-row lg:justify-between lg:items-center gap-4 mb-6 lg:mb-8">
        <h2 className="text-2xl lg:text-3xl font-bold">
          Categories Management
        </h2>

        <Button
          onClick={() => setShowAddForm(!showAddForm)}
          className="bg-black text-white hover:bg-gray-800 flex items-center space-x-2"
        >
          <Plus size={20} />
          <span>{showAddForm ? "Cancel" : "Add Category"}</span>
        </Button>
      </div>

      {/* Add Category Form */}
      {showAddForm && (
        <div className="bg-white rounded-lg p-4 lg:p-6 shadow mb-6 lg:mb-8 space-y-4">
          <input
            type="text"
            placeholder="Category Name"
            className="w-full px-4 py-2 border rounded-lg text-sm lg:text-base"
            onChange={(e) => setName(e.target.value)}
          />

          <Button
            onClick={() => CreateCategory(formData)}
            className="w-full bg-black text-white hover:bg-gray-800"
            disabled={isLoading}
          >
            Add Category
          </Button>
        </div>
      )}

      {categoriesLoading && (
        <div className="flex justify-center py-10">
          <div className="w-6 h-6 border-4 border-gray-300 border-t-black rounded-full animate-spin"></div>
        </div>
      )}

      {/* Categories List */}
      <div className="bg-white rounded-lg shadow overflow-hidden">
        {/* MOBILE VIEW */}
        <div className="lg:hidden divide-y">
          {categories?.map((cat) => (
            <div key={cat.id} className="p-4 space-y-3">
              <div className="font-medium capitalize">{cat.name}</div>
              <div className="text-sm text-gray-600">Slug: {cat.name}</div>

              <div className="flex justify-between items-center">
                <span className="text-sm">{cat.products.length} products</span>

                <div className="flex space-x-2">
                  <button
                    onClick={() => openEditModal(cat)}
                    className="text-blue-600 text-sm"
                  >
                    Edit
                  </button>
                  <button
                    onClick={() => deleteCategory(cat.id)}
                    className="text-red-600 text-sm"
                  >
                    Delete
                  </button>
                </div>
              </div>
            </div>
          ))}
        </div>

        {/* DESKTOP VIEW */}
        <div className="hidden lg:block overflow-x-auto">
          <table className="w-full text-sm">
            <thead className="bg-gray-100 border-b">
              <tr>
                <th className="text-left py-4 px-6">Category Name</th>
                <th className="text-left py-4 px-6">Slug</th>
                <th className="text-left py-4 px-6">Products</th>
                <th className="text-center py-4 px-6">Actions</th>
              </tr>
            </thead>

            <tbody>
              {categories.map((cat) => (
                <tr key={cat.id} className="border-b hover:bg-gray-50">
                  <td className="py-4 px-6 font-medium">{cat.name}</td>
                  <td className="py-4 px-6">{cat.name}</td>
                  <td className="py-4 px-6">{cat.products.length}</td>

                  <td className="py-4 px-6 text-center space-x-2">
                    <button
                      onClick={() => openEditModal(cat)}
                      className="text-blue-600 hover:underline"
                    >
                      Edit
                    </button>
                    <button
                      onClick={() => deleteCategory(cat.id)}
                      className="text-red-600 hover:underline"
                    >
                      Delete
                    </button>
                  </td>
                </tr>
              ))}
            </tbody>
          </table>
        </div>
      </div>

      {/* EDIT MODAL */}
      {editingId && (
        <div className="fixed inset-0 bg-black/40 backdrop-blur-sm flex items-center justify-center z-50">
          <div className="bg-white rounded-lg p-6 w-[90%] max-w-md shadow-xl space-y-4">
            <div className="flex justify-between items-center">
              <h2 className="text-xl font-bold">Edit Category</h2>
              <button onClick={closeEditModal}>
                <X className="w-6 h-6 text-gray-600" />
              </button>
            </div>

            <input
              type="text"
              value={editedName}
              onChange={(e) => setEditedName(e.target.value)}
              className="w-full px-4 py-2 border rounded-lg"
              placeholder="Enter new category name"
            />

            <div className="flex justify-end space-x-3 pt-2">
              <button
                onClick={closeEditModal}
                className="px-4 py-2 border rounded-lg"
              >
                Cancel
              </button>

              <button
                onClick={handleSaveEdit}
                className="px-4 py-2 bg-blue-600 text-white rounded-lg"
              >
                Save
              </button>
            </div>
          </div>
        </div>
      )}
    </div>
  );
}
